import json, glob
from collections import Counter
for f in sorted(glob.glob('task_*.messages.json')):
    msgs=json.load(open(f))
    # find consecutive identical assistant tool calls
    cmds=[]
    for m in msgs:
        if m['role']=='assistant':
            for tc in (m.get('tool_calls') or []):
                cmds.append(tc.get('function',{}).get('arguments'))
    # count max run of identical consecutive commands
    maxrun=1; cur=1
    for i in range(1,len(cmds)):
        if cmds[i]==cmds[i-1]: cur+=1; maxrun=max(maxrun,cur)
        else: cur=1
    # also count identical tool RESULTS consecutive
    res=[]
    for m in msgs:
        if m['role']=='tool':
            c=m.get('content')
            if isinstance(c,list): c=' '.join(str(x) for x in c)
            res.append((c or '')[:200])
    rmax=1;rcur=1
    for i in range(1,len(res)):
        if res[i]==res[i-1]: rcur+=1; rmax=max(rmax,rcur)
        else: rcur=1
    rj=json.load(open(f.replace('.messages.json','.result.json')))
    if maxrun>=2 or rmax>=3:
        print(f.split('.')[0], 'reward=',rj['reward'],'exit=',rj['agent']['exit_reason'],'maxCmdRun=',maxrun,'maxResRun=',rmax)
"

